@Component("underwriter-handler")
@ProcessingGroup("underwriter-processing-group")
public class UnderwriterEventHandler {
	
	// core constructor
	UnderwriterEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateUnderwriterEvent
     */
    @EventHandler
    public void handle( CreateUnderwriterEvent event) {
        entityManager.persist(new Underwriter(event.getUnderwriterId(), event.getFirstName(), event.getLastName(), event.getEmployeeId(), event.getAuthorityLimit(), event.getDecisions(), event.getInsurer()));
    }

    /*
     * @param	event UpdateUnderwriterEvent
     */
    @EventHandler
    public Underwriter handle( UpdateUnderwriterEvent event) {
    	entityManager.merge(new Underwriter(event.getUnderwriterId(), event.getFirstName(), event.getLastName(), event.getEmployeeId(), event.getAuthorityLimit(), event.getDecisions(), event.getInsurer()));
    }
    
    /*
     * @param	event DeleteUnderwriterEvent
     */
    @EventHandler
    public void on( DeleteUnderwriterEvent event) {
    	Underwriter entity = new Underwriter();
   
    	// ------------------------------------------
    	// apply the UnderwriterId
    	// ------------------------------------------
    	entity.setUnderwriterId( event.getUnderwriterId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final UnderwriterRepository underwriterEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(UnderwriterEventHandler.class.getName());

}
